vec4 rendreTunnelInterieur(vec2 coordonneeFragment) {
    vec2 resolutionEcran = iResolution.xy;
    vec4 couleurAccumulee = vec4(0.0);
    float tempsAnime = iTime * 1.5;

    float indexEtape = 0.0;
    float distanceProfondeur = 0.0;
    float distanceEstimationSurface = 0.0;
    float echelleFractale = 0.0;

    for (int etapeMarchage = 0; etapeMarchage < 200; etapeMarchage++) {
        if (indexEtape + distanceProfondeur >= 200.0) {
            break;
        }
        indexEtape += 1.0;

        vec3 directionRayonProjection = distanceProfondeur * normalize(vec3((coordonneeFragment * 2.0 - resolutionEcran) / resolutionEcran.y, 1.2));
        directionRayonProjection.z += tempsAnime * 4.5;

        float angleRotationTorsion = -sin(directionRayonProjection.z * 0.15) * 0.7 - tempsAnime * 0.3;
        mat2 matriceRotationXZ = mat2(
            cos(angleRotationTorsion), -sin(angleRotationTorsion),
            sin(angleRotationTorsion), cos(angleRotationTorsion)
        );
        directionRayonProjection.xy *= matriceRotationXZ;

        vec3 positionPerturbee = directionRayonProjection;
        for (echelleFractale = 0.3; echelleFractale < 18.0; echelleFractale /= 0.6) {
            positionPerturbee += (abs(sin(positionPerturbee.zxy * echelleFractale + vec3(0.0, tempsAnime * 0.6, tempsAnime * 0.9))) - 0.55) / echelleFractale;
        }

        float distanceFormeTunnel = abs(length(directionRayonProjection.xy) - 1.8 + cos(directionRayonProjection.z * 0.6 - tempsAnime) * 0.8) / 8.0;
        distanceEstimationSurface = 0.003 + distanceFormeTunnel;
        distanceEstimationSurface += abs(positionPerturbee.y * 0.02);

        distanceProfondeur += distanceEstimationSurface;

        vec3 couleurMotifGradation = mix(
            vec3(0.8, 0.1, 0.6),
            vec3(0.1, 0.9, 0.7),
            0.5 + 0.5 * cos(directionRayonProjection.z * 0.2 - tempsAnime)
        );

        float intensiteLuminescence = exp(-distanceProfondeur * 0.09) / (distanceEstimationSurface * 80.0 + 0.008);
        couleurAccumulee.rgb += couleurMotifGradation * intensiteLuminescence;
    }

    return couleurAccumulee;
}

void mainImage(out vec4 couleurFragment, in vec2 coordonneeFragment) {
    vec2 coordonneesUV = coordonneeFragment / iResolution.xy;

    vec4 couleurArrierePlan = texture(iChannel0, coordonneesUV);
    vec4 couleurTunnelAvantPlan = rendreTunnelInterieur(coordonneeFragment);

    vec3 couleurFinaleComposee = couleurArrierePlan.rgb + couleurTunnelAvantPlan.rgb * 0.75;
    couleurFinaleComposee = tanh(couleurFinaleComposee * 0.025);

    couleurFragment = vec4(couleurFinaleComposee, 1.0);
}

vec4 rendreTunnelEspaceTemps(vec2 coordonneeFragment) {
    vec2 resolutionEcran = iResolution.xy;
    vec4 couleurAccumulee = vec4(0.0);
    float tempsAnime = iTime;

    float indexEtape = 0.0;
    float distanceProfondeur = 0.0;
    float distanceEstimationSurface = 0.0;
    float echelleFractale = 0.0;

    for (int etapeMarchage = 0; etapeMarchage < 300; etapeMarchage++) {
        if (indexEtape + distanceProfondeur >= 300.0) {
            break;
        }
        indexEtape += 1.0;

        vec3 directionRayonProjection = distanceProfondeur * normalize(vec3((coordonneeFragment * 2.0 - resolutionEcran) / resolutionEcran.y, 1.2));
        directionRayonProjection.z += tempsAnime * 3.0;

        float angleRotationTorsion = sin(directionRayonProjection.z * 0.1) * 0.5 + tempsAnime * 0.2;
        mat2 matriceRotationXZ = mat2(
            cos(angleRotationTorsion), -sin(angleRotationTorsion),
            sin(angleRotationTorsion), cos(angleRotationTorsion)
        );
        directionRayonProjection.xy *= matriceRotationXZ;

        vec3 positionPerturbee = directionRayonProjection;
        for (echelleFractale = 0.2; echelleFractale < 24.0; echelleFractale /= 0.55) {
            positionPerturbee += (abs(sin(positionPerturbee.yzx * echelleFractale + vec3(tempsAnime * 0.8, tempsAnime * 0.4, 0.0))) - 0.6) / echelleFractale;
        }

        float distanceFormeTunnel = abs(length(directionRayonProjection.xy) - 3.5 + sin(directionRayonProjection.z * 0.4 + sin(tempsAnime)) * 1.2) / 10.0;
        distanceEstimationSurface = 0.002 + distanceFormeTunnel;
        distanceEstimationSurface += abs(positionPerturbee.x * 0.015);

        distanceProfondeur += distanceEstimationSurface;

        vec3 couleurVortexTemporal = mix(
            vec3(0.05, 0.25, 0.9),
            vec3(0.95, 0.35, 0.05),
            0.5 + 0.5 * sin(directionRayonProjection.z * 0.15 + tempsAnime * 0.5)
        );
        couleurVortexTemporal += vec3(0.1, 0.4, 0.8) * cos(directionRayonProjection.z * 0.3 - tempsAnime);

        float intensiteLuminescence = exp(-distanceProfondeur * 0.06) / (distanceEstimationSurface * 60.0 + 0.005);
        couleurAccumulee.rgb += couleurVortexTemporal * intensiteLuminescence;
    }

    return vec4(couleurAccumulee.rgb, 1.0);
}

void mainImage(out vec4 couleurFragment, in vec2 coordonneeFragment) {
    vec4 couleurSuperEchantillonnee = vec4(0.0);

    vec2 decalagesAntialiasing[4];
    decalagesAntialiasing[0] = vec2(-0.25, -0.25);
    decalagesAntialiasing[1] = vec2( 0.25, -0.25);
    decalagesAntialiasing[2] = vec2(-0.25,  0.25);
    decalagesAntialiasing[3] = vec2( 0.25,  0.25);

    for (int indexEchantillon = 0; indexEchantillon < 4; indexEchantillon++) {
        couleurSuperEchantillonnee += rendreTunnelEspaceTemps(coordonneeFragment + decalagesAntialiasing[indexEchantillon]);
    }

    couleurFragment = couleurSuperEchantillonnee * 0.25;
}
